const AuthContext = createContext(null)
function useAuth() { return useContext(AuthContext) }

function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    try { return JSON.parse(localStorage.getItem('zenheaven_user')) } catch { return null }
  })
  const [authLoading, setAuthLoading] = useState(false)

  const signIn = async (credentials, mode = 'login') => {
    setAuthLoading(true)
    try {
      const result = await api(`/auth/${mode}`, { method: 'POST', body: JSON.stringify(credentials) })
      localStorage.setItem('zenheaven_token', result.access_token)
      localStorage.setItem('zenheaven_user', JSON.stringify(result.user))
      setUser(result.user)
      return result
    } finally { setAuthLoading(false) }
  }
  const signOut = () => {
    localStorage.removeItem('zenheaven_token')
    localStorage.removeItem('zenheaven_user')
    setUser(null)
  }
  const value = useMemo(() => ({ user, setUser, signIn, signOut, authLoading }), [user, authLoading])
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

